import{_ as o,o as s,c as r,a0 as n}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"推荐 v0.3（配队 + 副本/BOSS 对策，独立推导）","description":"","frontmatter":{},"headers":[],"relativePath":"llm_reco/reco-team.md","filePath":"llm_reco/reco-team.md"}'),a={name:"llm_reco/reco-team.md"};function d(e,t,l,i,g,c){return s(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="推荐-v0-3-配队-副本-boss-对策-独立推导" tabindex="-1">推荐 v0.3（配队 + 副本/BOSS 对策，独立推导） <a class="header-anchor" href="#推荐-v0-3-配队-副本-boss-对策-独立推导" aria-label="Permalink to &quot;推荐 v0.3（配队 + 副本/BOSS 对策，独立推导）&quot;">​</a></h1><blockquote><p>在 v0.2「单卡强度」基础上，结合<strong>讨伐战/副本机制</strong>与<strong>编队接力系统</strong>，给出可落地的配队方案。 数据来源：<code>raid.md</code>（各 BOSS 参数，事实）、<code>raid-formations.md</code>（编队机制，事实）、<code>char_data.json</code>（角色机制，已核验）。 <strong>依然不参考</strong> <code>raid-recommended.md</code>（官方推荐名单）。本版结论由&quot;BOSS 机制需求 → 所需对策机制 → 角色数据匹配&quot;推导。 配套推理见 <code>reasoning-log.md</code>（v0.3 增补节）。</p></blockquote><h2 id="_0-先纠正一个根本误解-上场-5-人-单队决战" tabindex="-1">0. 先纠正一个根本误解：上场 5 人 ≠ 单队决战 <a class="header-anchor" href="#_0-先纠正一个根本误解-上场-5-人-单队决战" aria-label="Permalink to &quot;0. 先纠正一个根本误解：上场 5 人 ≠ 单队决战&quot;">​</a></h2><p><code>raid.md</code> 关键事实：</p><ul><li><strong>体力每秒扣 2%</strong>（无续航 50 秒全退场），且该费用为百分比——<strong>体力/双防数值完全无效</strong>，高血量与高防在 raid 里没用。</li><li>战斗<strong>无时间限制</strong>，单队打不完，因此高分打法是<strong>多队接力</strong>：<code>优先1</code>(5人) → <code>优先2</code>(15人) → <code>替补</code> → <code>星面50人编队</code>。</li><li>&quot;分队伍&quot;的真正含义是<strong>接力轮换</strong>，不是同场多队。我的配队建议必须给出&quot;首发队 + 接力队&quot;结构，而不是只列 5 人。</li></ul><h2 id="_1-配队铁律-从-raid-机制推出" tabindex="-1">1. 配队铁律（从 raid 机制推出） <a class="header-anchor" href="#_1-配队铁律-从-raid-机制推出" aria-label="Permalink to &quot;1. 配队铁律（从 raid 机制推出）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>铁律</th><th>推导</th></tr></thead><tbody><tr><td><strong>减伤率 debuff（降防）&gt;&gt; 攻击 buff</strong></td><td>面对 75% 减伤 BOSS，降防带来的伤害提升是攻 buff 的 <strong>3 倍</strong>；60% 减伤时为 1.5 倍。仅 50% 减伤的古纳冈两者等价。→ 优先堆降防到 80%+，其次攻 buff</td></tr><tr><td><strong>单体 + 领域同名效果叠加生效</strong></td><td>同类多角色放同款只取最高（浪费）；但&quot;角色单体型&quot;与&quot;领域型&quot;叠加。→ 一单体一领域搭配最高效</td></tr><tr><td><strong>必杀充能辅助是得分核心</strong></td><td>FEVER 中必杀发动次数=得分主来源；不早点出必杀=全队裸装。→ 充能/提速位是刚需</td></tr><tr><td><strong>默认带治疗</strong></td><td>除非防御叠到 100% 减伤（受 1 点伤害）否则要奶；持续治疗 &gt; 一次性群疗</td></tr><tr><td><strong>BREAK 比控时更值</strong></td><td>破防灯亮=BOSS 眩晕+1.5 倍伤害+重置攻击计时；时间停止收益保守。→ 带&quot;确定点灯&quot;角色优于纯时停</td></tr></tbody></table><h2 id="_2-通用-5-人首发模板-适合多数-boss" tabindex="-1">2. 通用 5 人首发模板（适合多数 BOSS） <a class="header-anchor" href="#_2-通用-5-人首发模板-适合多数-boss" aria-label="Permalink to &quot;2. 通用 5 人首发模板（适合多数 BOSS）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[主输出] 单体高倍率必杀（自带降防/攻buff/充能 更佳）</span></span>
<span class="line"><span>[生存辅助] 防御buff 或 BOSS降攻 debuff（单体+领域叠到 50%+）</span></span>
<span class="line"><span>[输出辅助] 降防 debuff 或 攻buff（叠到 80% 减伤降低）</span></span>
<span class="line"><span>[治疗] 持续回复型（兼免控/解控最佳）</span></span>
<span class="line"><span>[自由位] 追加输出 / 必杀充能 / 提速 之一</span></span></code></pre></div><p><strong>角色落位（全部来自 v0.2 已核验数据）：</strong></p><ul><li>主输出：ブライドハルカ・リバース(不撤退+攻521+即死) / 超昂閃忍ナリカ(复活+双修) / 閃忍マユリ(R, 15×无视防御核弹)</li><li>生存辅助：ビートアミュレット・ノノノ(R, 全队攻防±30) / 神騎アルゴル(R, 速度场+全队充能)</li><li>输出辅助（降防核心）：鬼の斗羽大洋(SSR, 全体攻防−60%！顶级减益) / 魔女ミヤビ(SSR, 敌方防速−20%)</li><li>治疗：制服ニャンコ(SSR, 免控领域+治疗) / 六の法杖セラフィール(SSR, 被动解控+治疗) / 魔女シズク(R, 廉价群疗)</li><li>自由位：妹の1024(SSR, 充能核心) / 真夏のイーイー(SSR, 攻击buff+眩晕抵抗)</li></ul><blockquote><p>减伤降低凑不到 80% 时，把&quot;输出辅助&quot;位再塞一个降防手（如 神騎ハニーエル R 的魔免+免疫，或第二降防角色）。</p></blockquote><h2 id="_2b-团队构建方法论-v0-4-如何从-370-角色里挑出-5-人均衡队" tabindex="-1">2b. 团队构建方法论（v0.4）：如何从 370 角色里挑出 5 人均衡队 <a class="header-anchor" href="#_2b-团队构建方法论-v0-4-如何从-370-角色里挑出-5-人均衡队" aria-label="Permalink to &quot;2b. 团队构建方法论（v0.4）：如何从 370 角色里挑出 5 人均衡队&quot;">​</a></h2><blockquote><p>用户追问：光比输出不够，还要<strong>生存</strong>（治疗/减伤/免控）和<strong>增益</strong>（攻击速度、必杀充能非常重要），但<strong>同场只上 5 人</strong>。怎么从 370 人里调出一队&quot;输出+生存+增益齐全&quot;？ 方法不靠官方名单，靠对 <code>char_data.json</code> 全量打&quot;队伍职能标签&quot;后做覆盖分析（脚本 <code>_team_build.py</code>，产物 <code>_team_build.txt</code>）。</p></blockquote><h3 id="_2b-1-核心矛盾-5-框塞不下-5-个单职专家" tabindex="-1">2b.1 核心矛盾：5 框塞不下&quot;5 个单职专家&quot; <a class="header-anchor" href="#_2b-1-核心矛盾-5-框塞不下-5-个单职专家" aria-label="Permalink to &quot;2b.1 核心矛盾：5 框塞不下&quot;5 个单职专家&quot;&quot;">​</a></h3><p>一个 raid 均衡队<strong>最少</strong>要覆盖 5 个职能：输出、降防、速度、充能、治疗（生存）。若每人只干一件事，需要 ≥6 槽——<strong>超出 5 人上限，不可能</strong>。 <strong>唯一解法 = 职能密度</strong>：挑&quot;一人兼多职&quot;的角色，把多个职能压进 5 框。</p><h3 id="_2b-2-全量职能稀缺度-char-data-json-实测-持有角色数" tabindex="-1">2b.2 全量职能稀缺度（char_data.json 实测，持有角色数） <a class="header-anchor" href="#_2b-2-全量职能稀缺度-char-data-json-实测-持有角色数" aria-label="Permalink to &quot;2b.2 全量职能稀缺度（char_data.json 实测，持有角色数）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职能</th><th>总数</th><th>SSR/SR/R</th><th>含义</th></tr></thead><tbody><tr><td>不撤退</td><td><strong>8</strong></td><td>3/1/4</td><td>极稀缺，raid 居座/高难主线神</td></tr><tr><td>复活</td><td><strong>1</strong></td><td>1/0/0</td><td>全游戏唯一（超昂閃忍ナリカ）</td></tr><tr><td>降防</td><td>46</td><td>41/1/4</td><td>raid 进攻核心，偏稀缺</td></tr><tr><td>解控</td><td>19</td><td>16/0/3</td><td>中稀缺</td></tr><tr><td>增伤</td><td>54</td><td>49/1/4</td><td>进攻放大器</td></tr><tr><td>减伤</td><td>60</td><td>50/1/9</td><td>生存主力</td></tr><tr><td>免疫</td><td>62</td><td>46/1/15</td><td>免控领域</td></tr><tr><td>治疗</td><td>99</td><td>76/8/15</td><td>生存刚需</td></tr><tr><td>充能</td><td>102</td><td>82/4/16</td><td>用户强调：FEVER 得分核心</td></tr><tr><td>速度</td><td>126</td><td>96/6/24</td><td>用户强调：行动次数</td></tr><tr><td>攻buff</td><td>110</td><td>95/4/11</td><td>进攻加分项</td></tr><tr><td>硬控</td><td>112</td><td>80/5/27</td><td>确定点灯（BREAK）</td></tr><tr><td>输出</td><td>~全</td><td>—</td><td>高倍率必杀≈人人有，从不缺</td></tr></tbody></table><p><strong>读表</strong>：真正卡脖子的稀缺职能是 <strong>不撤退(8)/复活(1)/降防(46)</strong>；速度/充能虽用户强调&quot;非常重要&quot;，但持有量充足（126/102），<strong>可轻松塞进队伍</strong>，关键是选&quot;同时带速度/充能 + 别的职能&quot;的高密度角色。</p><h3 id="_2b-3-职能密度-370-人里有多少人-一人顶多人" tabindex="-1">2b.3 职能密度：370 人里有多少人&quot;一人顶多人&quot; <a class="header-anchor" href="#_2b-3-职能密度-370-人里有多少人-一人顶多人" aria-label="Permalink to &quot;2b.3 职能密度：370 人里有多少人&quot;一人顶多人&quot;&quot;">​</a></h3><ul><li>覆盖 <strong>≥3 职能</strong>：46 人</li><li>覆盖 <strong>≥4 职能</strong>：37 人</li><li>覆盖 <strong>≥5 职能</strong>：10 人</li><li>覆盖 <strong>≥6 职能</strong>：7 人（如 小鬼の斗羽大洋：免疫+减伤+治疗+硬控+输出+降防，单卡顶 6 职）</li></ul><p>→ 池子足够大，<strong>5 框塞满齐全队伍完全可行</strong>，关键是优先选高密度卡。</p><h3 id="_2b-4-贪心覆盖算法拼出的-4-套队-强制职能先补-再用余槽堆稀有权重" tabindex="-1">2b.4 贪心覆盖算法拼出的 4 套队（强制职能先补，再用余槽堆稀有权重） <a class="header-anchor" href="#_2b-4-贪心覆盖算法拼出的-4-套队-强制职能先补-再用余槽堆稀有权重" aria-label="Permalink to &quot;2b.4 贪心覆盖算法拼出的 4 套队（强制职能先补，再用余槽堆稀有权重）&quot;">​</a></h3><p>每槽标注其覆盖职能；&quot;主职&quot;加粗。</p><p><strong>A. 顶配均衡队（5/5 强制覆盖，生存完整，总覆盖 13 职能）</strong></p><ol><li><strong>エスカサファイア・ムーンライズ</strong>(SSR)：减伤/增伤/攻buff/硬控/解控/<strong>输出</strong>/<strong>速度</strong> — 主输出+提速+增幅</li><li><strong>小鬼の斗羽大洋</strong>(SSR)：免疫/减伤/治疗/硬控/<strong>输出</strong>/<strong>降防</strong> — 降防核+治疗+免控（单卡顶 4 关键职）</li><li><strong>ダンスクイーン・ピカ</strong>(SSR)：<strong>充能</strong>/免疫/攻buff/硬控/输出/<strong>速度</strong> — 充能核心+提速</li><li><strong>超昂閃忍ナリカ</strong>(SSR)：免疫/<strong>复活</strong>/输出 — 唯一复活位（保底）</li><li><strong>FM77</strong>(R)：<strong>不撤退</strong>/减伤 — 不撤退廉价值（高难主线也通用）</li></ol><p><strong>B. 新手友好队（仅 R/SR，5/5 覆盖，生存完整）</strong></p><ol><li><strong>ビートノーブル・カノン</strong>(R)：免疫/攻buff/硬控/解控/<strong>速度</strong> — 提速+免控</li><li><strong>閃忍フクシュウチャン</strong>(SR)：治疗/硬控/输出/<strong>降防</strong> — 降防+治疗</li><li><strong>ビートアミュレット・ノノノ</strong>(R)：<strong>充能</strong>/减伤/降防 — 充能+降防</li><li><strong>FM77</strong>(R)：<strong>不撤退</strong>/减伤</li><li><strong>ビートアイドル・タマキ</strong>(R)：充能/增伤 — 补充能+增幅</li></ol><p><strong>C. 高难 raid 居座队（强制含 不撤退，5/5 覆盖）</strong></p><ol><li>エスカサファイア・ムーンライズ(SSR) 2. 小鬼の斗羽大洋(SSR) 3. ダンスクイーン・ピカ(SSR)</li><li><strong>ブライドハルカ・リバース</strong>(SSR)：<strong>不撤退</strong>/减伤/增伤/攻buff/输出 — 不撤退+自buff 居座</li><li>超昂閃忍ナリカ(SSR)（复活保底）</li></ol><p><strong>D. 暴力输出队（强制 2 输出+降防+充能+治疗）</strong>：同 A 骨架，输出权重拉满。</p><h3 id="_2b-5-给用户的-挑选流程-一句话总结" tabindex="-1">2b.5 给用户的&quot;挑选流程&quot;一句话总结 <a class="header-anchor" href="#_2b-5-给用户的-挑选流程-一句话总结" aria-label="Permalink to &quot;2b.5 给用户的&quot;挑选流程&quot;一句话总结&quot;">​</a></h3><ol><li>先列&quot;必覆盖清单&quot;（输出+降防+速度+充能+治疗+1项生存保险）。</li><li>在 <code>char_data.json</code> 按职能标签筛，优先<strong>密度≥3</strong>的卡填稀缺职（不撤退/复活/降防）。</li><li>用余槽补&quot;速度/充能&quot;——这两职能人多，专挑&quot;顺带兼速度/充能&quot;的高密度卡，别占用独立槽。</li><li>5 槽排满后，多队接力照样按此模板复制（优先2/替补）。</li></ol><h2 id="_3-七大-boss-对策映射-参数→需求→推荐" tabindex="-1">3. 七大 BOSS 对策映射（参数→需求→推荐） <a class="header-anchor" href="#_3-七大-boss-对策映射-参数→需求→推荐" aria-label="Permalink to &quot;3. 七大 BOSS 对策映射（参数→需求→推荐）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>BOSS</th><th>关键参数</th><th>必需对策机制</th><th>推荐角色（核验来源）</th></tr></thead><tbody><tr><td><strong>黄金甜心</strong></td><td>减伤50% / 眩晕抗75% / <strong>魔法伤害减半</strong></td><td>物理队优先；魔法队必带&quot;咬甜心王子&quot;装备；攻间隔长(10-15s)易叠 buff</td><td>物理输出为主；降防手 鬼の斗羽大洋；治疗 制服ニャンコ</td></tr><tr><td><strong>古纳冈</strong></td><td>减伤50% / 眩晕抗<strong>最低50%</strong> / <strong>领域持续1%/s伤害</strong></td><td><strong>持续治疗</strong>（抵消领域伤害）；易 BREAK</td><td>持续奶 制服ニャンコ/六の法杖セラフィール/魔女雫流(兑换)；BREAK 用 閃忍クサリ(R, 强制眩晕)</td></tr><tr><td><strong>乌塔尔</strong></td><td>减伤65% / <strong>小猫机制</strong>(需全体攻击或全体异常清小猫)</td><td><strong>全体攻击必杀</strong> 或 <strong>全体异常状态必杀</strong>(点亮BREAK清小猫)</td><td>体育祭のヤブルー(SSR, 全体魅惑+束缚=同时清小猫+点灯) / 全体AoE输出</td></tr><tr><td><strong>堕威大佛</strong></td><td>减伤60% / <strong>眩晕抗高+即死10倍·魅惑5倍</strong> / <strong>破防灯仅3格</strong></td><td><strong>确定点灯</strong>(无视抗性)维持破防；BREAK灯少→手动撤退续灯</td><td>エスカ・アメイズ(R, 必中魅惑=抗性中也点灯) / 閃忍クサリ(R, 强制眩晕点灯) / 不撤退 ビートソニック・アキレス</td></tr><tr><td><strong>大往女</strong></td><td>减伤60% / <strong>眩晕攻击附带束缚</strong></td><td><strong>束缚免疫/解除</strong>（装备&quot;芬巴尔三兄弟&quot;或免控领域）</td><td>制服ニャンコ/魔女フタバ(R)/神騎ハニーエル(R) 的免控领域；六の法杖セラフィール 解控</td></tr><tr><td><strong>狂王</strong></td><td>减伤60% / <strong>小狂王随从</strong>(需全体必杀清)</td><td><strong>全体必杀</strong> 清随从</td><td>超昂闪忍成香成香系全体必杀 / 全体AoE输出</td></tr><tr><td><strong>弗栗多</strong></td><td><strong>伤害60%×4人极痛</strong> / 减伤75% / <strong>双形态破盾</strong> / <strong>减速收益极高</strong></td><td><strong>减速 debuff</strong>(行动越慢得分越高) + 破盾(降防100%) + 不撤退角色适配</td><td>减速角色(闪忍/魔女系，如風の風香+超昂闪忍成香昴 95%减速) + 超昂奈理卡(体力停25%居座) + 鬼の斗羽大洋(攻防−60%)</td></tr></tbody></table><h2 id="_4-多队接力结构示例-以通用-boss-为例" tabindex="-1">4. 多队接力结构示例（以通用 BOSS 为例） <a class="header-anchor" href="#_4-多队接力结构示例-以通用-boss-为例" aria-label="Permalink to &quot;4. 多队接力结构示例（以通用 BOSS 为例）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【首发 优先1】5人：主输出 + 生存辅助 + 降防手 + 治疗 + 充能核心</span></span>
<span class="line"><span>   → 目标：开场快速开 FEVER+BREAK（4.5倍窗口）</span></span>
<span class="line"><span>【接力 优先2】5人（同构或补降防/治疗）：</span></span>
<span class="line"><span>   → 首发退场后接管，维持降防覆盖与续航</span></span>
<span class="line"><span>【工具人（第6/7人，出击/退场即触发短时 buff）】：</span></span>
<span class="line"><span>   → 妹の1024(充能) / 真夏のイーイー(攻击buff) / 体育祭のヤブルー(全异常免疫+CC)</span></span>
<span class="line"><span>   → 短时效单体 buff 需配 超昂阿梅兹·幻梦 延长（高阶技巧，新人可暂忽略）</span></span></code></pre></div><p><strong>新手节奏（raid-formations 步骤）：</strong></p><ol><li>先满突 1 套优先1（5人）：主输出(★5) + 降防 + 攻buff + 治疗(★3) + 充能(R)。</li><li>再养优先2（5人）接力。</li><li>给首发 5 人装备&quot;重型星面&quot;→等效多出一支编队（35-5-5-5 多星面结构）。</li></ol><h2 id="_5-副本维度-非-raid" tabindex="-1">5. 副本维度（非 raid） <a class="header-anchor" href="#_5-副本维度-非-raid" aria-label="Permalink to &quot;5. 副本维度（非 raid）&quot;">​</a></h2><ul><li><strong>主线/EX 关</strong>：有战斗时间限制、防御/魔抗<strong>有效</strong>，与 raid 规则相反。此处<strong>站场+不撤退+高数值</strong>更重要 → v0.2 的 不撤退/复活 角色（超昂閃忍ナリカ、ビートソニック・アキレス）通用价值高。</li><li><strong>每日任务/宝箱狩猎</strong>：效率优先，AoE 全体角色（247人）与提速充能辅助最实用。</li><li><strong>高难本（暗影等）</strong>：控制/解控需求高 → 免控领域（制服ニャンコ/魔女フタバ R）+ 解控（六の法杖セラフィール）。</li></ul><h2 id="_6-与-v0-2-的修正" tabindex="-1">6. 与 v0.2 的修正 <a class="header-anchor" href="#_6-与-v0-2-的修正" aria-label="Permalink to &quot;6. 与 v0.2 的修正&quot;">​</a></h2><ul><li>v0.2 把&quot;攻击增益(3人)&quot;列为 S 级；v0.3 修正：<strong>降防 debuff（破防/贯通14人）在 raid 里比攻 buff 更核心</strong>（75%减伤时价值3倍）。攻击buff 仍稀有但定位降至&quot;输出辅助的加分项&quot;。</li><li>v0.2 单列&quot;不撤退&quot;为站场；v0.3 补充：<strong>raid 里体力按百分比扣、双防无效</strong>，不撤退的价值在 raid 中其实被稀释（不撤退≠不扣血，只是不强制退），真正适配 raid 居座的是&quot;体力停止衰减&quot;类（超昂奈理卡）。不撤退在高难主线才是真神。</li><li>v0.3 新增&quot;确定点灯&quot;对策位（堕威大佛/乌塔尔专用），恰好 my v0.2 的 R 卡 エスカ・アメイズ/閃忍クサリ 命中此需求——印证独立推理自洽。</li></ul><blockquote><p>诚实留白：弗栗多/乌塔尔专用的&quot;减速角色&quot;&quot;全体异常清小猫&quot;具体持有者需查 <code>raid.md</code> 减速表与角色全体必杀清单全量核实，本版仅给出机制方向与已核验示例。</p></blockquote><hr><h2 id="_5-强度量化模型-v0-8-·-raid-专用-·-真实频率公式-·-真实觉醒表-·-真实两件配装-单角色固定分-队伍考试式打分" tabindex="-1">5. 强度量化模型（v0.8 · RAID 专用 · 真实频率公式 · 真实觉醒表 · 真实两件配装）：单角色固定分 + 队伍考试式打分 <a class="header-anchor" href="#_5-强度量化模型-v0-8-·-raid-专用-·-真实频率公式-·-真实觉醒表-·-真实两件配装-单角色固定分-队伍考试式打分" aria-label="Permalink to &quot;5. 强度量化模型（v0.8 · RAID 专用 · 真实频率公式 · 真实觉醒表 · 真实两件配装）：单角色固定分 + 队伍考试式打分&quot;">​</a></h2><blockquote><p>用户要求：默认满星培养→<strong>单角色强度是固定值，可建数学模型</strong>；推荐时<strong>算出能打多少伤害、施加多少 buff/debuff</strong>（&quot;分数就是伤害，像考试&quot;）；新增角色只要读详情套模型即出分。 终局副本 4 种（raid / B宇宙 / 广域战 / 全域战），<strong>本模型只攻破 raid</strong>，其余三模式先占位（同框架接入只需换&quot;场景常量+适配层&quot;）。 为建通用模型，用户要求把除「角色 kit + 真实战斗细节」外的一切<strong>全固定为常数</strong>：BOSS（机制常亮·固定伤害·体力-2%/s·固定防御率 R）+ 角色（满星100级·觉醒+·觉醒属性强化满·<strong>两件真实主装</strong>）。R=0.50（古纳冈类）/ 连击阈值60%。 <strong>v0.7 修正（2026-07-30 用户给出真实觉醒表）</strong>：v0.6 觉醒常数错误（速+3%除法/充+15pt）。真实规则：行动速度 <strong>-0.1×20次=最多-2秒（扁平），强化下限 3sec</strong>；必杀充能 <strong>+0.3×20次=最多+6pt，强化上限 15%</strong>（基础≥15 不受益）；攻/魔 +20%（全员同幅）。连击率+20(上限50%)不采用（50/70 档已达上限无收益；0 档点了反拖慢必杀）。 <strong>v0.8 修正（2026-07-30 用户拍板真实配装）</strong>：删除全部副装贴片（多变量）与仁王纳豆（与部分角色技能效果冲突，多变量）。默认装备<strong>仅两件主装</strong>：火箭引擎/咆哮猛虎(满级) <strong>行动速度 -50%</strong>、冲击腰带(满级) <strong>攻魔 +50%</strong>。旧占位（主装+300 扁平 / 贴片B8降防30%·B1攻30%·B3速20%）全部作废——<strong>降防不再有 30% 打底，只剩角色 kit 自带</strong>。 实现：<code>llm_reco/_char_score.py</code>（只读 <code>char_data.json</code>，自动出分+分档+队伍打分）。<strong>复用：新增角色补进 <code>char_data.json</code> → 重跑 <code>python llm_reco/_char_score.py</code></strong>。真实战斗细节（行動速度/必殺充填量/連撃率）由 <code>extract_chars.py</code> 抽 <code>詳細ステータス</code>。</p></blockquote><h3 id="_5-1-单角色固定强度-part1-场景全固定→强度只取决于-kit-真实战斗细节" tabindex="-1">5.1 单角色固定强度（Part1，场景全固定→强度只取决于 kit + 真实战斗细节） <a class="header-anchor" href="#_5-1-单角色固定强度-part1-场景全固定→强度只取决于-kit-真实战斗细节" aria-label="Permalink to &quot;5.1 单角色固定强度（Part1，场景全固定→强度只取决于 kit + 真实战斗细节）&quot;">​</a></h3><p><strong>特征</strong>（char_data.json 正则解析 + combat 真实字段）：<code>base=max(攻撃力,魔法力)</code>@lv100；必杀倍率（只认 canon「敵〇〇N倍」，觉醒取最大）；降防%/攻buff%/增伤%/guard%（文本正则）；<strong>真实战斗细节</strong>（extract_chars.py 抽 詳細ステータス）：<code>行動速度(sec)</code> / <code>必殺充填量(%)</code> / <code>連撃率(%)</code>；flag：奶/免疫/不撤退/复活/硬控/解控/减速。 <strong>固定场景常量（均一行可改）</strong>：FEVER=3 / CRIT=1.25 / BREAK=1.5 / 装备(火箭速-50%·腰带攻魔+50%，仅此两件) / 觉醒强化(真实表：速-2s下限3s/充+6pt上限15%/攻魔+20%) / <strong>固定防御率 R=0.50（古纳冈类）</strong> / 連撃阈值60%。 <strong>损伤频率模型（battle.md 机制，分数即秒伤；v0.8 用真实数据+真实觉醒表+真实两件配装）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eff_speed   = max(行動速度(sec) - 2.0, 3.0)   # 觉醒扁平-2秒，强化下限3sec（已≤3无收益）</span></span>
<span class="line"><span>interval     = eff_speed × (1 - 火箭50%) / (1 + 自身速buff)   # 行动间隔(秒)</span></span>
<span class="line"><span>interval_ult= interval × (1 + 連撃率)         # 连击使行动计量条不前进→必杀/普攻节奏变慢</span></span>
<span class="line"><span>atks/s      = 1 / interval_ult</span></span>
<span class="line"><span>charge_eff  = 必殺充填量%≥15 ? 原值 : min(必殺充填量%+6, 15)   # 觉醒+6pt上限15%</span></span>
<span class="line"><span>必杀casts/s = (charge_eff/100) / interval_ult</span></span>
<span class="line"><span>combo_mult  = 1 + Σ 連撃率ⁿ×decay(n), decay=0.8/0.6/0.4/0.3(≥4击)   # 连击追加伤害(不暴击)</span></span>
<span class="line"><span>red_coeff   = 1 - 0.50*(1 - min(1, 降防))     # 降防只剩角色 kit 自带（副装已删）</span></span>
<span class="line"><span>crit = 1.25（腰带+50%全员常驻→稳定触发，全员一致不影响排名）;  break_m = 1.5 if 硬控 else 1.0</span></span>
<span class="line"><span>base_hit = base×1.20 × (1+攻buff+0.50) × (1+增伤) × red_coeff   # ×1.20=觉醒攻魔+20%；+0.50=腰带</span></span>
<span class="line"><span>normal_DPS = (base_hit·crit + base_hit·(combo_mult-1)) × atks/s      # 基础击暴击，连击追加不暴击</span></span>
<span class="line"><span>ult_DPS   = base_hit × 必杀倍率 × 3(FEVER) × break_m × 必杀casts/s</span></span>
<span class="line"><span>DPS = normal_DPS + ult_DPS</span></span></code></pre></div><p><strong>辅助/生存分</strong>（BOSS机制常亮→必须覆盖）：<code>100·复活 + 60·不撤退 + 40·免疫 + 35·奶 + 30·解控 + 25·硬控 + 30·guard%</code>。 <strong>综合强度</strong> = <code>0.70·DPS归一(0-100) + 0.30·UTIL归一(0-100)</code>；分档 <strong>T0(前10%)/T1(前30%)/T2(前60%)/T3</strong>。</p><h3 id="_5-2-验证-370-角色实跑-v0-8-·-真实觉醒表-真实两件配装" tabindex="-1">5.2 验证（370 角色实跑 v0.8 · 真实觉醒表 + 真实两件配装） <a class="header-anchor" href="#_5-2-验证-370-角色实跑-v0-8-·-真实觉醒表-真实两件配装" aria-label="Permalink to &quot;5.2 验证（370 角色实跑 v0.8 · 真实觉醒表 + 真实两件配装）&quot;">​</a></h3><ul><li>maxDPS=6,595；maxUTIL=140。</li><li><strong>修复连击率百分/小数单位 bug</strong>（v0.6 已修）：combat 字段连击率以 %(如 30) 存储，公式原误当小数(1+30=31 倍减速)致连击角色 DPS 塌缩 1/30；现 kit_of 转小数(0.30)后排名自洽。</li><li><strong>必杀倍率 artifact 仍封死</strong>：只认「敵〇〇N倍」+ 严格兜底「必殺威力×N」，排除「人数×N%必杀威力アップ」团队缩放。</li><li><strong>v0.8 排名再洗牌（副装降防 30% 打底删除 → kit 自带降防价值暴涨）</strong>：レジェンド・ハルカ(78.9, 降防100%) 重回 TOP1，反超 幻忍コテツ(75.4, 降防60% 但 DPS分100 仍是 maxDPS 持有者)；黒門天(73.0, 降防100%×10) / ブライド・スバル(61.3) / 真夏のハルカ(55.3) / 閃忍アキラ(53.4)。<strong>洞察：v0.7 里人人白嫖 30% 降防打底，kit 降防被稀释；v0.8 降防归零打底后「降防 100% vs 60%」= 削减系数 1.00 vs 0.80 = 25% 伤害差，直接改写头名。</strong></li><li>觉醒下限 3s 拉平基础速度的洞察仍成立（火箭 -50% 是乘法，对全员等比，不改相对排名）。</li><li><strong>連撃型验证</strong>：连击率≥60% 仅 3 人，必杀占比 正月の切裂余命 68.8% / 体育祭のキリエル 39.5% / バビロニア・ニル 13.1%——バビロニア・ニル 普攻DPS(3,149) ≫ 必杀DPS(476)。</li></ul><h3 id="_5-3-队伍考试式打分-part2-v0-4-四队-·-固定场景-7-boss-适配层" tabindex="-1">5.3 队伍考试式打分（Part2，v0.4 四队 · 固定场景 + 7 BOSS 适配层） <a class="header-anchor" href="#_5-3-队伍考试式打分-part2-v0-4-四队-·-固定场景-7-boss-适配层" aria-label="Permalink to &quot;5.3 队伍考试式打分（Part2，v0.4 四队 · 固定场景 + 7 BOSS 适配层）&quot;">​</a></h3><p>每 BOSS：队伍聚合降防/攻buff/增伤/硬控 + 各成员自身 interval/必杀充填量 → 求和 DPS × fit_mult（乌塔尔/狂王需全体、堕威大佛需硬控/全体、大往女需免疫/解控、古纳冈需治疗、弗栗多需减速/不撤退）。</p><table tabindex="0"><thead><tr><th>队伍</th><th>综合平均秒伤(v0.8)</th><th>备注</th></tr></thead><tbody><tr><td><strong>D.暴力输出队</strong></td><td><strong>42,281</strong></td><td>raw 46,979；5 纯输出(降防100%×9~×10 → red_coeff=1.00 完全免削减)，乌塔尔/狂王因缺全体 fit 0.60/0.70 扣分</td></tr><tr><td>C.居座队</td><td>16,529</td><td>降防max60%(仅kit)×居座(体力停衰)，全 BOSS 稳</td></tr><tr><td>A.顶配均衡队</td><td>12,541</td><td>5/5 对策覆盖，均衡</td></tr><tr><td>B.新手R/SR队</td><td>7,344</td><td>仅 R/SR 可成型</td></tr></tbody></table><blockquote><p>读表（v0.8 数字，结论与 v0.6/v0.7 一致且 D 优势扩大）：① <strong>D 暴力输出队 raw DPS 碾压</strong>（46,979 vs C 17,062）——副装降防删除后 D 的 kit 降防 100% 独享 red_coeff=1.00，而 C/A/B 只剩 kit 降防 50~60%，<strong>降防差距被进一步放大</strong>；② C 居座队靠体力停衰适配全 BOSS 最稳；③ A 均衡队 5/5 覆盖但 DPS 居中；④ B 新手队最弱仍 &gt;0（R/SR 也能打）。</p></blockquote><h3 id="_5-4-诚实留白" tabindex="-1">5.4 诚实留白 <a class="header-anchor" href="#_5-4-诚实留白" aria-label="Permalink to &quot;5.4 诚实留白&quot;">​</a></h3><ul><li><strong>觉醒强化（v0.7 已按用户真实觉醒表定死）</strong>：速 -0.1×20=-2s 扁平(下限3s) / 充 +0.3×20=+6pt(上限15%) / 攻魔+20%。常数在 <code>_char_score.py</code> 顶部 <code>AWK_SPEED_SEC/AWK_SPEED_FLOOR/AWK_CHARGE/AWK_CHARGE_CAP/AWK_ATK</code>。注意：上限 3s/15% 是&quot;强化不能越过的线&quot;，非人人可达——强化次数有限（速最多-2/充最多+6）。</li><li><strong>觉醒连击率 +20(上限50%) 未采用</strong>：基础 50/70 档已达/超上限无收益；0 档必杀型点了 interval_ult×1.2 反拖慢必杀，理性不点。若想全员默认点满，改 kit_of 连击率一行即可。</li><li><strong>装备（v0.8 已按用户拍板定死）</strong>：仅两件主装——火箭 -50% 行动速度（乘法 <code>×(1-0.50)</code>，作用于觉醒后的 eff_speed）/ 腰带攻魔 +50%（与角色攻 buff 加算）。常数 <code>EQ_ROCKET_SPEED/EQ_BELT_ATK</code>。副装贴片与仁王纳豆按用户要求删除（多变量；纳豆与部分角色技能效果冲突）。火箭作用顺序（先觉醒扁平后装备乘法）为模型假设，若游戏实际是先乘后减，3s 下限角色数值会略变但排名几乎不动。</li><li><strong>R=0.50（Step3 确认，古纳冈类）</strong>：降防收益=攻buff 1 倍（R/(1-R)=1）；若改最难 75% 为基准，改 <code>R_ref</code> 一行，降防权重随 §7.6 升至 3 倍，排名微调。</li><li><strong>连击率阈值 60%（Step3 确认）</strong>：基础连击率只有 0/50/70 三档跳变，60% 仅命中 3 人；模型对连击用连续惩罚因子(interval×(1+連撃率))，不是硬二分类。</li><li>真实战斗细节来自 <code>char_data.json.combat</code>（extract_chars.py 抽 詳細ステータス），若源站数值更新重跑 extract 即可。</li><li>固定装备套数值（主装+300/副装三件套）据 equipment.md 合理设定；若实战标准配装不同改常量块即可。</li><li>UTIL 点为主观稀缺度赋权；DPS/UTIL 0.70/0.30 为折中。队伍 <code>fit_mult</code> 为 BOSS 对策经验系数，非严格推导。</li></ul>`,59)])])}const h=o(a,[["render",d]]);export{p as __pageData,h as default};
